-- Professional AAC default board templates — replaces the original
-- first-words / basic-needs / full-board content with vocabulary chosen
-- against professional AAC references (Project Core's Universal Core 36,
-- Tobii Dynavox's TD Snap Core First, and the Israeli "אפשר לומר" generic
-- boards from מרכז אומר), and adds a fourth, more advanced template.
--
-- Every card carries a part_of_speech (Modified Fitzgerald Key — see
-- supabase/migrations/0028_aac_part_of_speech.sql and the --pos-* tokens in
-- frontend/css/tokens.css) so board.js colours it correctly whether or not
-- it also sits inside a category folder. Root-level `cards` (no enclosing
-- category) render on the child's home page ahead of the folder tiles —
-- board_templates.apply_to_child seeds those via _seed_cards before walking
-- `categories` (see backend/app/repositories/board_templates.py).
--
-- Templates are copied into a child's own aac_categories/aac_cards rows at
-- child-creation time (board_templates.apply_to_child) and never linked
-- afterwards, so this migration does not touch any existing child's board.
--
-- Every symbol_id below resolves against a shipped Mulberry Symbols row
-- (0011/0013/0026/0029) — verified by backend/tests/test_symbol_consistency.py.

update board_templates set
  name_he = 'מילים ראשונות',
  description_he = '12 מילות ליבה להתחלה — ללא תיקיות, כרטיס אחד לכל מגע.',
  spec = '{"cards":[{"label":"אני","symbol_id":"i","part_of_speech":"pronoun","grid_order":0},{"label":"רוצה","symbol_id":"want","part_of_speech":"verb","grid_order":1},{"label":"עוד","symbol_id":"more","part_of_speech":"adjective","grid_order":2},{"label":"לא","symbol_id":"no","part_of_speech":"negation","grid_order":3},{"label":"כן","symbol_id":"yes","part_of_speech":"negation","grid_order":4},{"label":"עזרה","symbol_id":"help","part_of_speech":"verb","grid_order":5},{"label":"לאכול","symbol_id":"eat","part_of_speech":"verb","grid_order":6},{"label":"לשתות","symbol_id":"drink","part_of_speech":"verb","grid_order":7},{"label":"לשחק","symbol_id":"play","part_of_speech":"verb","grid_order":8},{"label":"מספיק","symbol_id":"stop","part_of_speech":"negation","grid_order":9},{"label":"גמרתי","symbol_id":"finished","part_of_speech":"negation","grid_order":10},{"label":"שלום","symbol_id":"hello","part_of_speech":"social","grid_order":11}]}'::jsonb
where id = 'first-words';

